  e     jsonb;
  v_imp numeric;
  v_pes numeric;
  v_acc numeric;
  v_arr jsonb;
  v_n   int;
  v_k   int;
  o     record;
  v_ok  int := 0;
  v_mal int := 0;
  v_fallas text := '';
begin
  for e in select * from jsonb_array_elements(d) loop
    begin
      if not exists (select 1 from public.v_pagos_facturas where id = (e->>'i')::bigint and sin_imputar) then
        continue;
      end if;
      select imputable into v_imp from public.pagos_facturas where id = (e->>'i')::bigint;
      select sum(value::numeric), count(*) into v_pes, v_n from jsonb_each_text(e->'o');
      v_arr := '[]'::jsonb; v_acc := 0; v_k := 0;
      for o in select key, value::numeric as peso from jsonb_each_text(e->'o') order by value::numeric loop
        v_k := v_k + 1;
        v_arr := v_arr || jsonb_build_object('obra_cod', o.key,
                   'monto', case when v_k = v_n then v_imp - v_acc else round(v_imp * o.peso / v_pes, 2) end);
        v_acc := v_acc + round(v_imp * o.peso / v_pes, 2);
      end loop;
      perform public.pagos_imputar_factura((e->>'i')::bigint, (e->>'c')::bigint, v_arr, null, u);
      v_ok := v_ok + 1;
    exception when others then
      v_mal := v_mal + 1;
      v_fallas := v_fallas || (e->>'i') || ' ' || left(sqlerrm, 40) || '; ';
    end;
  end loop;
  raise notice 'Imputadas: %. No imputadas: % (%)', v_ok, v_mal, left(v_fallas, 3000);
end $m$;
